"use client";

import React, { useState, useMemo } from "react";
import { 
  CalendarDays, MapPin, Flag, ChevronDown, 
  Filter, Calendar 
} from "lucide-react";

/* --- 1. STRESS TEST DATASET (Jan has 12 events) --- */
const HOLIDAYS_DB = [
  // --- JANUARY 2026 (12 Events) ---
  { id: 101, name: "New Year's Day", date: "Jan 01", monthIdx: 0, day: "Thu", year: "2026", type: "Public", country: "Global", region: "All" },
  { id: 102, name: "World Introvert Day", date: "Jan 02", monthIdx: 0, day: "Fri", year: "2026", type: "Optional", country: "Global", region: "All" },
  { id: 103, name: "Lohri", date: "Jan 13", monthIdx: 0, day: "Tue", year: "2026", type: "Optional", country: "India", region: "North India" },
  { id: 104, name: "Makar Sankranti", date: "Jan 14", monthIdx: 0, day: "Wed", year: "2026", type: "Optional", country: "India", region: "Telangana" },
  { id: 105, name: "Pongal", date: "Jan 14", monthIdx: 0, day: "Wed", year: "2026", type: "Optional", country: "India", region: "Karnataka" },
  { id: 106, name: "Army Day", date: "Jan 15", monthIdx: 0, day: "Thu", year: "2026", type: "Public", country: "India", region: "All" },
  { id: 107, name: "MLK Day", date: "Jan 19", monthIdx: 0, day: "Mon", year: "2026", type: "Public", country: "USA", region: "All" },
  { id: 108, name: "Netaji Jayanti", date: "Jan 23", monthIdx: 0, day: "Fri", year: "2026", type: "Optional", country: "India", region: "All" },
  { id: 109, name: "Girl Child Day", date: "Jan 24", monthIdx: 0, day: "Sat", year: "2026", type: "Optional", country: "India", region: "All" },
  { id: 110, name: "Republic Day", date: "Jan 26", monthIdx: 0, day: "Mon", year: "2026", type: "National", country: "India", region: "All" },
  { id: 111, name: "Privacy Day", date: "Jan 28", monthIdx: 0, day: "Wed", year: "2026", type: "Optional", country: "Global", region: "All" },
  { id: 112, name: "Martyrs' Day", date: "Jan 30", monthIdx: 0, day: "Fri", year: "2026", type: "Public", country: "India", region: "All" },

  // --- FEB ---
  { id: 201, name: "Presidents' Day", date: "Feb 16", monthIdx: 1, day: "Mon", year: "2026", type: "Public", country: "USA", region: "All" },
  
  // --- MAR ---
  { id: 301, name: "Maha Shivaratri", date: "Mar 08", monthIdx: 2, day: "Sun", year: "2026", type: "Optional", country: "India", region: "All" },
  { id: 302, name: "Holi", date: "Mar 14", monthIdx: 2, day: "Sat", year: "2026", type: "Optional", country: "India", region: "All" },
  { id: 303, name: "Ugadi", date: "Mar 19", monthIdx: 2, day: "Thu", year: "2026", type: "Optional", country: "India", region: "Telangana" },
  
  // --- APR ---
  { id: 401, name: "Good Friday", date: "Apr 03", monthIdx: 3, day: "Fri", year: "2026", type: "Public", country: "Global", region: "All" },
  
  // --- MAY ---
  { id: 501, name: "Labor Day", date: "May 01", monthIdx: 4, day: "Fri", year: "2026", type: "Public", country: "Global", region: "All" },
  { id: 502, name: "Memorial Day", date: "May 25", monthIdx: 4, day: "Mon", year: "2026", type: "Public", country: "USA", region: "All" },

  // --- AUG ---
  { id: 801, name: "Independence Day", date: "Aug 15", monthIdx: 7, day: "Sat", year: "2026", type: "National", country: "India", region: "All" },
  
  // --- NOV ---
  { id: 1101, name: "Kannada Rajyotsava", date: "Nov 01", monthIdx: 10, day: "Sun", year: "2026", type: "Optional", country: "India", region: "Karnataka" },
  
  // --- DEC ---
  { id: 1201, name: "Christmas", date: "Dec 25", monthIdx: 11, day: "Fri", year: "2026", type: "Public", country: "Global", region: "All" },
];

const MONTH_NAMES = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const YEAR_OPTIONS = ["2024", "2025", "2026", "2027", "2028", "2029"];

const REGIONS_BY_COUNTRY: any = {
    "All": ["All", "Telangana", "Karnataka", "North India", "New York"],
    "India": ["All", "Telangana", "Karnataka", "North India"],
    "USA": ["All", "New York", "California"],
    "Global": ["All"]
};

export default function SixColumnHolidayGrid() {
  const [year, setYear] = useState("2026");
  const [country, setCountry] = useState("All");
  const [region, setRegion] = useState("All");
  const [type, setType] = useState("All");

  const monthData = useMemo(() => {
    const filtered = HOLIDAYS_DB.filter((h) => {
      const matchYear = h.year === year;
      const matchCountry = country === "All" || h.country === country || h.country === "Global";
      const matchRegion = region === "All" || h.region === region || h.region === "All";
      const matchType = type === "All" || h.type === type;
      return matchYear && matchCountry && matchRegion && matchType;
    });

    const groups: Record<number, typeof filtered> = {};
    for(let i=0; i<12; i++) groups[i] = [];
    filtered.forEach(h => groups[h.monthIdx].push(h));
    return groups;
  }, [year, country, region, type]);

  return (
    <div className="flex-1 h-screen overflow-y-auto bg-[#F8F9FC] dark:bg-[#09090b] flex flex-col">
      
      {/* --- HEADER --- */}
      <header className="sticky top-0 z-30 bg-white dark:bg-[#121212] border-b border-slate-200 dark:border-slate-800 px-6 py-3 shadow-sm flex-none">
         <div className="flex flex-col xl:flex-row items-center justify-between gap-4">
            <div className="flex items-center gap-3 w-full xl:w-auto">
               <div className="p-2 bg-brand-50 text-brand-600 rounded-lg">
                  <CalendarDays size={18} />
               </div>
               <div>
                  <h1 className="text-lg font-bold text-slate-900 dark:text-white leading-none">Holiday Dashboard</h1>
                  <p className="text-xs font-medium text-slate-500 mt-0.5">Year at a Glance • {year}</p>
               </div>
            </div>

            <div className="flex items-center gap-2 w-full xl:w-auto">
                <div className="bg-slate-100 dark:bg-slate-800 p-0.5 rounded-lg flex items-center mr-2">
                    {['All', 'Public', 'Optional'].map((t) => (
                        <button key={t} onClick={() => setType(t)} className={`px-3 py-1.5 rounded-md text-[10px] font-bold uppercase tracking-widest transition-all ${type === t ? "bg-white dark:bg-slate-600 text-slate-900 dark:text-white shadow-sm" : "text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"}`}>{t}</button>
                    ))}
                </div>
                <CompactSelect icon={<Flag size={14} />} value={country} onChange={(v: string)=>{setCountry(v); setRegion('All')}} options={['All', 'India', 'USA']} />
                <CompactSelect icon={<MapPin size={14} />} value={region} onChange={setRegion} options={REGIONS_BY_COUNTRY[country] || ['All']} disabled={country === 'Global'} />
                <CompactSelect icon={<Filter size={14} />} value={year} onChange={setYear} options={YEAR_OPTIONS} highlight={true} />
            </div>
         </div>
      </header>

      {/* --- 6-COLUMN GRID --- */}
      <main className="flex-1 p-6 overflow-hidden">
         <div className="h-full grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-4">
            {MONTH_NAMES.map((monthName, idx) => {
                const holidays = monthData[idx];
                const isActive = holidays.length > 0;
                
                return (
                    <div 
                        key={monthName}
                        className={`
                            flex flex-col rounded-xl border transition-all duration-300 overflow-hidden h-full
                            ${isActive 
                                ? "bg-white dark:bg-[#121212] border-slate-200 dark:border-slate-800 hover:border-brand-500/50 hover:shadow-md" 
                                : "bg-slate-50/50 dark:bg-white/[0.02] border-transparent opacity-60"
                            }
                        `}
                    >
                        {/* Month Header */}
                        <div className={`px-4 py-3 flex justify-between items-center border-b ${isActive ? 'border-slate-50 dark:border-slate-800' : 'border-transparent'}`}>
                            <h3 className={`text-xs font-black uppercase tracking-widest ${isActive ? 'text-slate-900 dark:text-white' : 'text-slate-400'}`}>
                                {monthName}
                            </h3>
                            {isActive && (
                                <span className="text-[9px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-500 px-1.5 py-0.5 rounded-full">
                                    {holidays.length}
                                </span>
                            )}
                        </div>

                        {/* Scrollable Events List */}
                        {/* We use flex-1 and overflow-y-auto here to allow scrolling INSIDE the card if needed */}
                        <div className="flex-1 overflow-y-auto p-2 space-y-2 custom-scrollbar">
                            {isActive ? (
                                holidays.map((h: any) => (
                                    <div key={h.id} className="group flex gap-2 items-center p-1.5 rounded-lg hover:bg-slate-50 dark:hover:bg-white/5 transition-colors cursor-default">
                                        {/* Date */}
                                        <div className="flex-shrink-0 w-8 h-8 rounded-md bg-slate-50 dark:bg-slate-800 flex flex-col items-center justify-center border border-slate-100 dark:border-slate-700">
                                            <span className="text-[11px] font-bold text-slate-700 dark:text-slate-200 leading-none">
                                                {h.date.split(' ')[1]}
                                            </span>
                                        </div>
                                        
                                        {/* Info */}
                                        <div className="flex-1 min-w-0">
                                            <p className="text-[10px] font-bold text-slate-900 dark:text-white truncate" title={h.name}>
                                                {h.name}
                                            </p>
                                            <div className="flex items-center gap-1">
                                                <div className={`w-1 h-1 rounded-full ${h.type === 'Optional' ? 'bg-amber-500' : 'bg-emerald-500'}`} />
                                                <span className="text-[8px] font-bold text-slate-400 uppercase truncate">
                                                    {h.type.substring(0,3)}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <div className="h-full flex items-center justify-center">
                                    <span className="text-[9px] font-bold text-slate-300 uppercase tracking-widest opacity-50">Empty</span>
                                </div>
                            )}
                        </div>
                    </div>
                );
            })}
         </div>
      </main>
    </div>
  );
}

/* --- UTILS --- */
const CompactSelect = ({ icon, value, onChange, options, disabled, highlight }: any) => (
   <div className={`relative h-8 min-w-[110px] ${disabled ? 'opacity-50 pointer-events-none' : ''}`}>
      <div className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none">{icon}</div>
      <select 
         value={value} 
         onChange={(e) => onChange(e.target.value)} 
         disabled={disabled}
         className={`w-full h-full pl-8 pr-6 text-[10px] font-bold uppercase tracking-widest outline-none cursor-pointer appearance-none rounded-lg border transition-all ${
            highlight 
            ? "bg-brand-50 text-brand-700 border-brand-100 dark:bg-brand-900/20 dark:text-brand-400 dark:border-brand-800" 
            : "bg-white text-slate-700 border-slate-200 hover:border-slate-300 dark:bg-slate-800 dark:text-slate-200 dark:border-slate-700"
         }`}
      >
         {options.map((opt: string) => <option key={opt} value={opt}>{opt}</option>)}
      </select>
      <ChevronDown size={12} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
   </div>
);